/**
 * dsh-notifier events 域 listen 块 —— 装配面：订阅宿主事件、转交翻译、把请求递给下游。
 *
 * 这一层是**装配面**（只伪 `events/deps.ts` 声明的端口），因此这里能测到别处测不到的两件事：
 *  1. 订阅与退订成对——少订阅一个口就是整整一类通知消失，漏退订一个口就是卸载后事件仍在灌；
 *  2. 完成判定的**时序**：`running` 起记、`idle` 结算，证据来自推送还是快照，取决于两刻之间
 *     会话日志长成了什么样。假 agent 的 `snapshotEvents()` 返回**可变数组**，就是为了摆出这个时序。
 *
 * 时间纪律：耗时按 running→idle 的墙钟差算，故用 `vi.setSystemTime` 钉住两刻（只换 `Date`，不碰
 * 事件循环）；`afterEach` 必须还原，否则同文件后续用例看到伪造的「现在」。
 */
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { SessionEvent } from "@deepseek-ai/dsh-session";
import type { ApprovalRequest } from "@deepseek-ai/dsh-user-approval";
import type { AskUserQuestionRequest } from "@deepseek-ai/dsh-user-questions";
import { afterEach, describe, expect, it, vi } from "vitest";

import type {
  AgentDisposedPayload,
  AgentErrorPayload,
  AgentRegistryPort,
  AgentStatusPayload,
  AgentTurnStoppingPayload,
  EventsDeps,
  HostEventPort,
  NotifyRequest,
} from "../../../src/server/events/deps.ts";
import { installEvents, releaseEvents } from "../../../src/server/events/interface.ts";
import { makeAgentRegistry, makeLogger } from "../../helpers.ts";

afterEach(() => {
  releaseEvents();
  vi.useRealTimers();
});

/** 宿主事件口能收到的负载里，本块只关心这几个字段。 */
const EVENT_NAMES = [
  "approval",
  "question",
  "session",
  "status",
  "disposed",
  "turnStopping",
  "error",
] as const;

type EventName = (typeof EVENT_NAMES)[number];

/** 任意函数：订阅口收下的 handler 形状各不相同，统一按「调用即触发」存。 */
type AnyHandler = (...args: never[]) => void;

/** 假宿主事件面：订阅进表、退订出表，`emit` 只送达**仍在表里**的 handler。 */
interface HostEvents {
  readonly port: HostEventPort;
  readonly subscribed: string[];
  readonly unsubscribed: string[];
  approval(request: ApprovalRequest): void;
  question(request: AskUserQuestionRequest): void;
  session(sessionId: string, event: SessionEvent): void;
  status(payload: AgentStatusPayload): void;
  disposed(payload: AgentDisposedPayload): void;
  turnStopping(payload: AgentTurnStoppingPayload): void;
  error(payload: AgentErrorPayload): void;
}

/**
 * 退订必须真的停止投递：只记「退订被调过」而不摘 handler，会掩盖「摘了订阅却仍产出」这一类
 * 回归——那正是插件卸载后通知还在弹的成因。
 */
function makeHostEvents(): HostEvents {
  const handlers = new Map<EventName, AnyHandler[]>();
  const subscribed: string[] = [];
  const unsubscribed: string[] = [];

  const take =
    <H extends AnyHandler>(name: EventName) =>
    (handler: H): (() => void) => {
      subscribed.push(name);
      const list = handlers.get(name) ?? [];
      list.push(handler);
      handlers.set(name, list);
      return () => {
        unsubscribed.push(name);
        const current = handlers.get(name) ?? [];
        const index = current.indexOf(handler);
        if (index !== -1) current.splice(index, 1);
      };
    };

  const emit = (name: EventName, ...args: unknown[]): void => {
    for (const handler of [...(handlers.get(name) ?? [])]) {
      (handler as (...rest: unknown[]) => void)(...args);
    }
  };

  const port: HostEventPort = {
    onApprovalRequest: take("approval"),
    onUserQuestion: take("question"),
    onSessionEvent: take("session"),
    onAgentStatus: take("status"),
    onAgentDisposed: take("disposed"),
    onAgentTurnStopping: take("turnStopping"),
    onAgentError: take("error"),
  };

  return {
    port,
    subscribed,
    unsubscribed,
    approval: (request) => emit("approval", request),
    question: (request) => emit("question", request),
    session: (sessionId, event) => emit("session", sessionId, event),
    status: (payload) => emit("status", payload),
    disposed: (payload) => emit("disposed", payload),
    turnStopping: (payload) => emit("turnStopping", payload),
    error: (payload) => emit("error", payload),
  };
}

/** 会话日志条目：判定只读 `type` 与 `data`。 */
function titleEvent(title: string): SessionEvent {
  return { type: "session/title", data: { title } } as unknown as SessionEvent;
}

function turnEndEvent(turn: number, kind = "completed"): SessionEvent {
  return { type: "turn/end", data: { turn, reason: { kind } } } as unknown as SessionEvent;
}

/** 一个假会话：日志**可变**，因为完成判定读的是「running 那一刻」与「idle 那一刻」两份快照。 */
interface FakeSession {
  readonly id: string;
  readonly agent: Agent;
  readonly log: SessionEvent[];
  endTurn(turn: number, kind?: string): void;
}

function makeSession(
  id: string,
  options: { title?: string; header?: Record<string, unknown> } = {},
): FakeSession {
  const log: SessionEvent[] = [];
  if (options.title !== undefined) log.push(titleEvent(options.title));
  const agent = {
    id,
    session: { header: options.header ?? {}, snapshotEvents: () => log },
  } as unknown as Agent;
  return {
    id,
    agent,
    log,
    endTurn: (turn, kind) => {
      log.push(turnEndEvent(turn, kind));
    },
  };
}

/** 装配一次 events 域，交出观测面。 */
function assemble(options: { agents?: AgentRegistryPort } = {}) {
  const events = makeHostEvents();
  const logger = makeLogger();
  const submitted: NotifyRequest[] = [];
  const deps: EventsDeps = {
    events: events.port,
    agents: options.agents ?? makeAgentRegistry(),
    logger,
    pipeline: {
      submit: (request) => {
        submitted.push(request);
      },
    },
  };
  installEvents(deps);
  return { events, logger, submitted };
}

/** 本域只读得懂 `status`；两个迁移包一层，免得每处都写一遍载荷。 */
function setStatus(events: HostEvents, session: FakeSession, status: "idle" | "running"): void {
  events.status({ agent: session.agent, status });
}

/** 钉住「现在」：只换 `Date`，不动定时器。 */
function at(hour: number, minute: number, second = 0): void {
  vi.setSystemTime(new Date(2026, 0, 15, hour, minute, second));
}

describe("装配与卸载", () => {
  it("装配订阅全部 7 个宿主事件口（少订阅一个就是整整一类通知消失）", () => {
    const { events } = assemble();
    expect([...events.subscribed].sort()).toEqual([...EVENT_NAMES].sort());
    expect(events.unsubscribed).toEqual([]);
  });

  it("release 逐个调用退订句柄，退订之后宿主事件不再进管线（否则卸载等于没生效）", () => {
    const { events, submitted } = assemble();
    events.approval({ toolName: "bash" } as unknown as ApprovalRequest);
    expect(submitted).toHaveLength(1);

    releaseEvents();
    expect([...events.unsubscribed].sort()).toEqual([...EVENT_NAMES].sort());

    events.approval({ toolName: "bash" } as unknown as ApprovalRequest);
    expect(submitted).toHaveLength(1);
  });

  it("重复装配当场抛错，而 release 之后装配能把订阅面装回来（卸载链可能走到不止一次）", () => {
    assemble();
    expect(() => assemble()).toThrow(/只能装配一次/u);
    releaseEvents();
    releaseEvents();
    // 只断言「没抛」不够：install 在 release 之后静默空转（插件热重载后彻底哑掉）同样不抛。
    const { events } = assemble();
    expect([...events.subscribed].sort()).toEqual([...EVENT_NAMES].sort());
  });
});

describe("转发：只有构成通知的事件才进管线", () => {
  it("审批请求 → ask 请求进管线，并带上会话标题", () => {
    const { events, submitted } = assemble();
    const session = makeSession("a-ask", { title: "修复登录" });
    events.approval({
      toolName: "bash",
      reason: "要跑测试",
      agent: session.agent,
    } as unknown as ApprovalRequest);
    expect(submitted).toHaveLength(1);
    expect(submitted[0]!.kind).toBe("ask");
    expect(submitted[0]!.body).toContain("修复登录");
  });

  it("用户在提问 → question 请求进管线", () => {
    const { events, submitted } = assemble();
    const session = makeSession("a-q", { title: "写文档" });
    events.question({
      questions: [{ id: "q1", question: "要哪个格式？" }],
      agent: session.agent,
    } as unknown as AskUserQuestionRequest);
    expect(submitted).toHaveLength(1);
    expect(submitted[0]!.kind).toBe("question");
    expect(submitted[0]!.body).toContain("要哪个格式？");
  });

  it("agent 出错 → error 请求进管线，且两次独立失败各报一条（把失败去重就等于静默第二次出错）", () => {
    const { events, submitted } = assemble();
    const session = makeSession("a-err", { title: "部署" });
    events.error({ agent: session.agent, turn: 2, step: 3, error: "连接超时" });
    events.error({ agent: session.agent, turn: 2, step: 3, error: "连接超时" });
    expect(submitted).toHaveLength(2);
    expect(submitted[0]!.kind).toBe("error");
    expect(submitted[0]!.body).toContain("连接超时");
  });

  it("agent 消亡与会话内事件都不产出通知（清账与记账本身不是通知）", () => {
    const { events, submitted } = assemble();
    const session = makeSession("a-quiet");
    events.disposed({ agent: session.agent });
    events.session(session.id, turnEndEvent(1));
    expect(submitted).toEqual([]);
  });
});

describe("完成判定：running 起记、idle 结算", () => {
  it("running → idle 且本轮 completed 落盘 → done，耗时取两刻墙钟差", () => {
    const { events, submitted } = assemble();
    const session = makeSession("c-done", { title: "跑测试" });

    at(12, 0, 0);
    setStatus(events, session, "running");
    session.endTurn(1);
    at(12, 0, 2);
    setStatus(events, session, "idle");

    expect(submitted).toHaveLength(1);
    expect(submitted[0]!.kind).toBe("done");
    expect(submitted[0]!.body).toBe("任务「跑测试」已完成\n耗时：2 秒");
  });

  it("running 本身不产出（起记不是完成，否则每轮开始都会弹一条「完成」）", () => {
    const { events, submitted } = assemble();
    setStatus(events, makeSession("c-running"), "running");
    expect(submitted).toEqual([]);
  });

  it("没有先 running 的 idle 不产出，也不留诊断（没跑过的 agent 不能造出一条假的完成）", () => {
    const { events, logger, submitted } = assemble();
    const session = makeSession("c-idle-only");
    session.endTurn(1);
    setStatus(events, session, "idle");
    expect(submitted).toEqual([]);
    expect(logger.warns).toEqual([]);
  });

  it("本轮是 aborted（用户中断）时不产出，并在日志里说清为什么（否则「为什么没发 done」无从查）", () => {
    const { events, logger, submitted } = assemble();
    const session = makeSession("c-abort");
    setStatus(events, session, "running");
    session.endTurn(1, "aborted");
    setStatus(events, session, "idle");
    expect(submitted).toEqual([]);
    expect(logger.warns).toHaveLength(1);
    expect(logger.warns[0]).toContain("agent=c-abort");
    expect(logger.warns[0]).toContain("kind=aborted");
  });

  it("没有任何 turn/end 证据时不产出（保守静默优于误报一条完成）", () => {
    const { events, logger, submitted } = assemble();
    const session = makeSession("c-no-evidence");
    setStatus(events, session, "running");
    setStatus(events, session, "idle");
    expect(submitted).toEqual([]);
    expect(logger.warns[0]).toContain("kind=none");
  });

  it("推送来的 turn/end 优先于快照：日志里还没有本轮结束时也能判定完成", () => {
    const { events, submitted } = assemble();
    const session = makeSession("c-push", { title: "推送判定" });

    events.session(session.id, turnEndEvent(5));
    setStatus(events, session, "running");
    setStatus(events, session, "idle");

    expect(submitted).toHaveLength(1);
    expect(submitted[0]!.kind).toBe("done");
  });

  it("同一份证据的第二次 idle 不重复通知（running 而不产生新轮次是常态）", () => {
    const { events, logger, submitted } = assemble();
    const session = makeSession("c-dedupe", { title: "去重" });

    events.session(session.id, turnEndEvent(5));
    setStatus(events, session, "running");
    setStatus(events, session, "idle");
    expect(submitted).toHaveLength(1);

    setStatus(events, session, "running");
    setStatus(events, session, "idle");
    expect(submitted).toHaveLength(1);
    expect(logger.warns[0]).toContain("记忆turn=5");
  });

  it("进入 running 时日志里已存在的 turn/end 是上一轮的（快照冻结）：不当作本轮完成", () => {
    const { events, logger, submitted } = assemble();
    const session = makeSession("c-frozen", { title: "旧证据" });
    session.endTurn(3);

    setStatus(events, session, "running");
    setStatus(events, session, "idle");

    expect(submitted).toEqual([]);
    expect(logger.warns[0]).toContain("证据源=快照冻结");
  });
});

describe("子代理归属：main 与 subagent 的 kind 分流", () => {
  it("origin=subagent 的会话报 subagent-done", () => {
    const { events, submitted } = assemble();
    const session = makeSession("s-origin", { title: "子任务", header: { origin: "subagent" } });
    setStatus(events, session, "running");
    session.endTurn(1);
    setStatus(events, session, "idle");
    expect(submitted[0]!.kind).toBe("subagent-done");
    expect(submitted[0]!.body).toContain("子任务「子任务」已完成");
  });

  it("父 agent 在册且确由它创建时报 subagent-done（运行时归属是 header 之外的第二个信号）", () => {
    const parent = makeSession("p-owner");
    const child = makeSession("s-owned", { header: { parentSession: "p-owner" } });
    const { events, submitted } = assemble({
      agents: makeAgentRegistry({ live: [parent.agent], owned: [["s-owned", "p-owner"]] }),
    });
    setStatus(events, child, "running");
    child.endTurn(1);
    setStatus(events, child, "idle");
    expect(submitted[0]!.kind).toBe("subagent-done");
  });

  it("父 agent 已消亡（查不到）时判主任务：宁可多报一条 done，也不静默用户自己的任务", () => {
    const { events, submitted } = assemble();
    const child = makeSession("s-orphan", { header: { parentSession: "p-gone" } });
    setStatus(events, child, "running");
    child.endTurn(1);
    setStatus(events, child, "idle");
    expect(submitted[0]!.kind).toBe("done");
  });
});

describe("turn 停止边界：同一 turn 只发一次", () => {
  it("同一 agent 的同一 turn 第二次到达不再产出，下一个 turn 照常产出", () => {
    const { events, submitted } = assemble();
    const session = makeSession("t-dedupe", { title: "任务A" });
    const payload = { agent: session.agent, turn: 3 } as AgentTurnStoppingPayload;

    events.turnStopping(payload);
    expect(submitted).toHaveLength(1);
    expect(submitted[0]!.kind).toBe("turn-end");
    expect(submitted[0]!.body).toBe("任务「任务A」第 3 轮工作已完成");

    events.turnStopping(payload);
    expect(submitted).toHaveLength(1);

    events.turnStopping({ agent: session.agent, turn: 4 } as AgentTurnStoppingPayload);
    expect(submitted).toHaveLength(2);
    expect(submitted[1]!.body).toContain("第 4 轮");
  });

  it("turn 不是有限数时不写出「第 NaN 轮」，且同一 agent 的这类轮次只发一次", () => {
    const { events, submitted } = assemble();
    const session = makeSession("t-nan", { title: "脏轮次" });
    const payload = { agent: session.agent, turn: Number.NaN } as AgentTurnStoppingPayload;

    events.turnStopping(payload);
    expect(submitted).toHaveLength(1);
    expect(submitted[0]!.body).toBe("任务「脏轮次」工作已完成");

    events.turnStopping(payload);
    expect(submitted).toHaveLength(1);
  });
});

describe("agent 消亡：只清账", () => {
  it("消亡清掉去重记账：同一个 agent id 的同一轮次在其消亡后可再次通知（会话 id 复用不该被旧账吞掉）", () => {
    const { events, submitted } = assemble();
    const session = makeSession("d-reuse", { title: "任务" });
    const payload = { agent: session.agent, turn: 3 } as AgentTurnStoppingPayload;

    events.turnStopping(payload);
    events.turnStopping(payload);
    expect(submitted).toHaveLength(1);

    events.disposed({ agent: session.agent });
    events.turnStopping(payload);
    expect(submitted).toHaveLength(2);
  });
});

packages/dsh-notifier/test/unit/api/prob.source:
/**
 * dsh-notifier api 域 probe 块 —— POST /test 与 GET /health。
 *
 * 判据面：测试通知必须走**同一条**裁决管线（不另开旁路），否则「测试能响、真实事件不响」这类问题
 * 会被测试本身掩盖；响应里的 `sseConnections` 进的是客户端「已发送至 N 个页面」的提示，报假数就是
 * 骗用户；`/health` 报的是**宿主平台**，客户端据此写系统通道的平台提示，拿浏览器 OS 猜
 * 会让 Windows 用户看到 Linux 的安装引导。
 */
import type { IncomingMessage, ServerResponse } from "node:http";
import { afterEach, describe, expect, it, vi } from "vitest";

import type {
  ChannelPort,
  HostCapabilities,
  NotifyRequest,
  PipelinePort,
} from "../../../src/server/api/deps.ts";
import { ProbeEndpoints } from "../../../src/server/api/impl/probe/index.ts";
import { streamHub } from "../../../src/server/api/impl/stream/index.ts";
import { jsonReq, makeLogger, makeRes, wire } from "../../helpers.ts";

/** 假能力面：调用次数要能被数（缓存判据靠它），平台值可注入（三平台格靠它），探测结论可注入失败。 */
function fakeChannels(
  options: { hostPlatform?: () => string; probe?: () => Promise<HostCapabilities> } = {},
) {
  let calls = 0;
  const port: ChannelPort = {
    probeCapabilities: () => {
      calls += 1;
      return options.probe === undefined ? Promise.resolve(CAPABILITIES) : options.probe();
    },
    hostPlatform: options.hostPlatform ?? (() => "linux"),
    undeterminedCapabilities: () => UNDETERMINED,
  };
  return { port, probeCalls: () => calls };
}

/** `/health` 上「无法判定」的**摘要**形状：能力面摘要是完整面的投影，不是同一个对象。 */
const UNDETERMINED_SUMMARY = {
  verdict: "unknown",
  unknownDimensions: ["popup", "sound"],
  popup: { state: "unknown" },
  sound: { state: "unknown" },
};

/** 「无法判定」的兜底形状（与服务端 `undeterminedCapabilities()` 同形，独立抄写才守得住漂移）。 */
const UNDETERMINED: HostCapabilities = {
  verdict: "unknown",
  unknownDimensions: ["popup", "sound"],
  popup: { state: "unknown", checked: [] },
  sound: { state: "unknown", players: [], toneFileAvailable: false, checked: [] },
  remediation: [],
};

/** 完整能力面夹具（含明细）：摘要与完整面的差异必须能被断言。 */
const CAPABILITIES: HostCapabilities = {
  verdict: "degraded",
  unknownDimensions: ["popup"],
  popup: {
    state: "unknown",
    checked: ["notify-send", "dbus-name-owner", "dbus-activatable", "session-bus"],
  },
  sound: {
    state: "degraded",
    players: ["pw-play"],
    toneFileAvailable: false,
    checked: ["players", "tone-file"],
  },
  remediation: [{ code: "host-no-tone-file" }],
};

/** 假请求：body 由 async 迭代器吐出（`readJsonBody` 走的就是这条路）。 */
function makeReq(
  options: { method?: string; body?: unknown; rawBody?: string } = {},
): IncomingMessage {
  return jsonReq({
    method: options.method ?? "POST",
    url: "/api/dsh-notifier/test",
    body: options.body,
    rawBody: options.rawBody,
  });
}

/** 假裁决管线：只记下提交体（该不该发、发去哪都是管线的事）。 */
function fakePipeline() {
  const submitted: NotifyRequest[] = [];
  const port: PipelinePort = {
    submit: (request) => {
      submitted.push(request);
    },
  };
  return { port, submitted };
}

/** POST 一次测试通知（给定请求对象）。 */
async function postWith(req: IncomingMessage) {
  const pipeline = fakePipeline();
  const { res, rec, json } = makeRes();
  await new ProbeEndpoints(pipeline.port, fakeChannels().port, makeLogger()).test(req, res);
  return { rec, json, pipeline };
}

/** POST 一次测试通知。 */
function post(request: { body?: unknown; rawBody?: string }) {
  return postWith(makeReq(request));
}

/** 块是字符串的请求（流被 `setEncoding` 过这类形态）：共享读取器承诺**不抛错**。 */
function makeStringChunkReq(): IncomingMessage {
  return {
    method: "POST",
    url: "/api/dsh-notifier/test",
    headers: { host: "127.0.0.1:3080" },
    socket: { remoteAddress: "127.0.0.1" },
    async *[Symbol.asyncIterator]() {
      yield '{"channelId":"bark:main"}';
    },
  } as unknown as IncomingMessage;
}

/** 读流中途出错的路由请求：客户端半途断开、socket 报错都长这样。 */
function makeBrokenReq(): IncomingMessage {
  return {
    method: "POST",
    url: "/api/dsh-notifier/test",
    headers: { host: "127.0.0.1:3080" },
    socket: { remoteAddress: "127.0.0.1" },
    async *[Symbol.asyncIterator]() {
      throw new Error("socket hang up");
    },
  } as unknown as IncomingMessage;
}

/**
 * 假 SSE 响应：连接表注册要 `on` / `destroyed` / `write` / `destroy`，其余方法用不到。
 *
 * 为什么要它：`sseConnections` 报的是服务端未释放的句柄数，未装配的枢纽恒为 0——断言里的
 * 字面量 0 因此恒真。真占住一个句柄才能把「报的是真实连接数」证伪。
 */
function makeSseRes(): ServerResponse {
  const rec = { destroyed: false };
  const res = {
    get destroyed() {
      return rec.destroyed;
    },
    get writableEnded() {
      return false;
    },
    writeHead() {
      return res;
    },
    write() {
      return true;
    },
    on() {
      return res;
    },
    destroy() {
      rec.destroyed = true;
    },
  };
  return res as unknown as ServerResponse;
}

afterEach(() => {
  streamHub.release();
});

describe("POST /test：测试通知走同一条裁决管线", () => {
  it("没有 body 时按全频道测试：提交固定的 test 文案，并报出服务端真实的 SSE 句柄数", async () => {
    streamHub.install({ logger: makeLogger() });
    streamHub.handle(makeReq({ method: "GET" }), makeSseRes());

    const { rec, json, pipeline } = await post({});
    expect(rec.status).toBe(200);
    expect(pipeline.submitted).toEqual([
      { kind: "test", title: "DSH：测试通知", body: "通知链路工作正常（此通知来自测试按钮）" },
    ]);
    expect(json()).toEqual({ ok: true, sseConnections: 1 });
  });

  it("带 channelId 时只多一个 onlyChannel（指定出口不能变成另一条通知文案）", async () => {
    const { pipeline } = await post({ body: { channelId: "bark:main" } });
    expect(pipeline.submitted).toEqual([
      {
        kind: "test",
        title: "DSH：测试通知",
        body: "通知链路工作正常（此通知来自测试按钮）",
        onlyChannel: "bark:main",
      },
    ]);
  });

  it.each<[string, unknown]>([
    ["空串", ""],
    ["数字", 42],
  ])("channelId 非法（%s）→ 400 且不提交", async (_label, channelId) => {
    const { rec, json, pipeline } = await post({ body: { channelId } });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { error: "测试通知参数非法", details: "channelId 必须为非空字符串或省略" },
    });
    expect(pipeline.submitted).toEqual([]);
  });
});

/**
 * 这个端点有副作用，所以「body 读不出来」不能退化成「没给 body」——后者会真的发一条通知出去。
 * 四类成因各自的文案都要落到响应里，客户端才能说清是体太大还是写错了。
 */
describe("POST /test：body 读不出来时 fail-closed（不许当成「没给 body」）", () => {
  it.each<[string, string, string]>([
    ["JSON 语法错", "{ not json", "请求体不是合法 JSON"],
    ["JSON 合法但是数字", "42", "请求体必须是 JSON 对象"],
    ["JSON 合法但是 null", "null", "请求体必须是 JSON 对象"],
  ])("%s → 400 invalid-json，一条都不提交", async (_label, rawBody, details) => {
    const { rec, json, pipeline } = await post({ rawBody });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({ ok: false, error: { code: "invalid-json", details } });
    expect(pipeline.submitted).toEqual([]);
  });

  it("超限体 → 400 invalid-json 且不提交：JSON 本身合法也不例外", async () => {
    const { rec, json, pipeline } = await post({ body: { channelId: "a".repeat(5000) } });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { code: "invalid-json", details: "请求体超出大小上限（4096 字节）" },
    });
    expect(pipeline.submitted).toEqual([]);
  });

  it("读流中断 → 400 invalid-json：半途断开不等于「没给 body」", async () => {
    const { rec, json, pipeline } = await postWith(makeBrokenReq());
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { code: "invalid-json", details: "请求体读取失败" },
    });
    expect(pipeline.submitted).toEqual([]);
  });

  it("块不是 Buffer 时也不抛错：按「读不出来」落 400，异常不许打到调用方", async () => {
    const { rec, json, pipeline } = await postWith(makeStringChunkReq());
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { code: "invalid-json", details: "请求体读取失败" },
    });
    expect(pipeline.submitted).toEqual([]);
  });

  it("纯空白 body 仍是「没给 body」：按全频道测试受理，不判畸形", async () => {
    const { rec, pipeline } = await post({ rawBody: "   \n\t " });
    expect(rec.status).toBe(200);
    expect(pipeline.submitted).toEqual([
      { kind: "test", title: "DSH：测试通知", body: "通知链路工作正常（此通知来自测试按钮）" },
    ]);
  });
});

describe("GET /health：报宿主平台、连接回收计数与能力面摘要", () => {
  it("platform 取 channels 域的平台事实（客户端据此写系统通道提示，不能拿浏览器 OS 猜），sseEvicts 形状与真实枢纽逐键一致", async () => {
    const { res, rec, json } = makeRes();
    const channels = fakeChannels({ hostPlatform: () => "darwin" });
    await new ProbeEndpoints(fakePipeline().port, channels.port, makeLogger()).health(
      makeReq({ method: "GET" }),
      res,
    );
    expect(rec.status).toBe(200);
    expect(json()).toEqual({
      ok: true,
      plugin: "dsh-notifier",
      // 端口注入的值而不是 process.platform：api 域直读进程全局会让这一格在 CI 上永远只有 linux 可达
      platform: "darwin",
      // 未装配占位：形状（键集）必须与真实枢纽一致，否则「未装配」与「装好但没淘汰过」在 /health 上长得不一样
      sseEvicts: {
        close: 0,
        error: 0,
        stalled: 0,
        maxage: 0,
        destroyed: 0,
        dispose: 0,
      },
      // 摘要：只给结论与维度状态，明细（checked / players / remediation）归 /diagnostics
      capabilities: {
        host: {
          verdict: "degraded",
          unknownDimensions: ["popup"],
          popup: { state: "unknown" },
          sound: { state: "degraded" },
        },
      },
    });
  });

  it("能力自检只探一次：连续两次请求共用同一个 Promise（每请求各探一次就是拿用户机器当靶场）", async () => {
    const channels = fakeChannels();
    const endpoints = new ProbeEndpoints(fakePipeline().port, channels.port, makeLogger());

    await endpoints.health(makeReq({ method: "GET" }), makeRes().res);
    await endpoints.health(makeReq({ method: "GET" }), makeRes().res);

    expect(channels.probeCalls()).toBe(1);
    // 摘要不得泄漏明细：客户端要靠 /diagnostics 才拿得到“下一步该干什么”
    const summary = makeRes();
    await endpoints.health(makeReq({ method: "GET" }), summary.res);
    expect(JSON.stringify(summary.json())).not.toContain("host-no-tone-file");
  });
});

describe("能力自检的兜底：诊断附属面不许把探活面拖下水", () => {
  it("探测抛错时 /health 不 500：既有键全在，能力面按「无法判定」上报并留恰好一条 warn", async () => {
    const channels = fakeChannels({ probe: () => Promise.reject(new Error("探测炸了")) });
    const logger = makeLogger();
    const endpoints = new ProbeEndpoints(fakePipeline().port, channels.port, logger);
    const { res, rec, json } = makeRes();
    await endpoints.health(makeReq({ method: "GET" }), res);

    expect(rec.status).toBe(200);
    const body = wire<{ ok: boolean; platform: string; capabilities: { host: HostCapabilities } }>(
      json(),
    );
    expect(body.ok).toBe(true);
    expect(body.platform).toBe("linux");
    expect(body.capabilities.host).toEqual(UNDETERMINED_SUMMARY);
    expect(logger.warns).toHaveLength(1);

    // 失败结论同样进缓存：不缓存会让每个请求都重新等一遍注定失败的探测
    await endpoints.health(makeReq({ method: "GET" }), makeRes().res);
    expect(channels.probeCalls()).toBe(1);
  });

  it("探测超过总预算即按「无法判定」上报（预算兜底必须真的会到点）", async () => {
    vi.useFakeTimers();
    try {
      const channels = fakeChannels({ probe: () => new Promise<HostCapabilities>(() => {}) });
      const endpoints = new ProbeEndpoints(fakePipeline().port, channels.port, makeLogger());
      const { res, json } = makeRes();
      const pending = endpoints.health(makeReq({ method: "GET" }), res);
      // 不引用具体预算值（引用它就等于把常量抄成第二份）：只要求它在 10s 内到点
      await vi.advanceTimersByTimeAsync(10_000);
      await pending;
      expect(wire<{ capabilities: { host: unknown } }>(json()).capabilities.host).toEqual(
        UNDETERMINED_SUMMARY,
      );
    } finally {
      vi.useRealTimers();
    }
  });
});

describe("GET /diagnostics：完整探测面", () => {
  it("给的是 channels 域那一份完整能力面（checked / players / remediation 都在）", async () => {
    const { res, rec, json } = makeRes();
    const channels = fakeChannels();
    await new ProbeEndpoints(fakePipeline().port, channels.port, makeLogger()).diagnostics(
      makeReq({ method: "GET" }),
      res,
    );
    expect(rec.status).toBe(200);
    const body = wire<{ platform: string; capabilities: { host: HostCapabilities } }>(json());
    expect(body.platform).toBe("linux");
    expect(body.capabilities.host).toEqual(CAPABILITIES);
    // 「响应体零原文」不在这层判：这里注入的是模块常量，`expect(JSON).not.toContain(...)` 结构上永远
    // 成立（一次实现改动都打不红）。真正的判据在域层——`remediation.params` 只由数据表产生，
    // 注入敌意 os-release 时域层用例会红。
  });
});

packages/dsh-notifier/test/unit/pipeline.source:
/**
 * dsh-notifier pipeline 域 service 块 —— 种类词汇表、装配面与归档。
 *
 * 判据为什么是这些：
 *  - 词汇表（`kinds.ts`）是裁决的坐标系：事件开关、`kindRoutes`、`allowKinds`、bark 紧急度全按它
 *    查，所以「内置 / 外部」的分界与强度的运行时白名单必须各自只有一份答案；
 *  - 装配面是单例：重复装配、卸载后仍收请求、卸载不清节奏状态，都是「上一个用例的状态漏进下一个」
 *    这类最难查的现场；
 *  - 归档是「为什么我没收到」的唯一答案来源，压制分支与发出分支都得留下记录。
 *
 * 装配纪律：`installPipeline` 是模块级单例，故每个用例后必须 `releasePipeline()`——否则下一个
 * `installPipeline` 当场抛「只能装配一次」，且逐频道节奏状态会跨用例延续。
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../../src/server/config/impl/model/type.ts";
import type { DeliverReason } from "../../../src/server/shared/interface.ts";
import type {
  ChannelsPort,
  HistoryEntry,
  NotifyMessage,
  OutgoingFrame,
  PipelineDeps,
} from "../../../src/server/pipeline/deps.ts";
import {
  BUILTIN_KINDS,
  KIND_SEVERITY,
  NOTIFY_SEVERITIES,
  isBuiltinKind,
  isNotifySeverity,
} from "../../../src/server/pipeline/impl/service/kinds.ts";
import {
  installPipeline,
  releasePipeline,
  submit,
} from "../../../src/server/pipeline/interface.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/interface.ts";
import { makeLogger, pollUntil, settleMicrotasks } from "../../helpers.ts";

/** 出站频道配置与帧载荷：经设置模型 / 域依赖声明可达，不必请别的块再导出一个名字。 */
type ChannelConfig = NotifyConfig["channels"][number];
type BarkConfig = Extract<ChannelConfig, { type: "bark" }>;

/** 装配面夹具：只伪 `pipeline/deps.ts` 声明的那几个端口，顺手记下四件观测物。 */
interface Harness {
  readonly deps: PipelineDeps;
  readonly history: HistoryEntry[];
  readonly statuses: Array<{
    channelId: string;
    status: "ok" | "failed";
    error: DeliverReason | undefined;
  }>;
  readonly delivered: Array<{ message: NotifyMessage; targets: readonly DeliveryTarget[] }>;
  readonly frames: OutgoingFrame[];
  readonly logger: ReturnType<typeof makeLogger>;
  /** 换掉这一刻生效的设置（设置是活的：装配期算出的快照会变成静态数据）。 */
  readonly useConfig: (patch?: Partial<NotifyConfig>) => void;
  /** 换掉投递出口的行为（缺省：全部送到）。 */
  readonly onDeliver: (deliver: ChannelsPort["deliver"]) => void;
}

type DeliveryTarget = Parameters<ChannelsPort["deliver"]>[1][number];

function configAt(patch: Partial<NotifyConfig> = {}): NotifyConfig {
  return { ...DEFAULT_CONFIG, ...patch };
}

function requestOf(over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind: "done", title: "标题", body: "正文", ...over };
}

function barkChannel(over: Partial<BarkConfig> = {}): BarkConfig {
  return {
    type: "bark",
    id: "a",
    enabled: true,
    baseUrl: "http://127.0.0.1:40281/bark",
    deviceKey: "dk",
    ...over,
  };
}

/** 默认表里的内置频道：泛型只为把「按 type 找到的那条」收窄成对应型号——查找条件就是 type 相等。 */
function builtinOf<T extends "browser" | "system">(type: T): Extract<ChannelConfig, { type: T }> {
  const found = DEFAULT_CONFIG.channels.find((channel) => channel.type === type);
  if (found === undefined) throw new Error(`默认表里缺内置频道 ${type}`);
  return found as Extract<ChannelConfig, { type: T }>;
}

/**
 * 两条内置出口都停用：`channels` 是唯一关得掉它们的地方——顶层 `browserNotify` / `systemSound`
 * 一类键现在只是读面派生出来的只读投影，改它们不会让内置出口少投一次。
 */
function builtinsOff(): ChannelConfig[] {
  return [
    { ...builtinOf("browser"), enabled: false },
    { ...builtinOf("system"), enabled: false },
  ];
}

/** 只留 system 出口的设置：节流用例要「唯一目标」才数得清投递次数。 */
function systemOnly(patch: Partial<NotifyConfig> = {}): Partial<NotifyConfig> {
  return {
    // 内置两频道恒在 `channels` 里：停用 browser，只留 system（弹窗开、声音关，这一次有实际动作）。
    channels: [
      { ...builtinOf("browser"), enabled: false },
      { ...builtinOf("system"), enabled: true, popup: true, sound: false },
    ],
    ...patch,
  };
}

function assemble(over: Partial<PipelineDeps> = {}): Harness {
  const history: HistoryEntry[] = [];
  const statuses: Harness["statuses"][number][] = [];
  const delivered: Harness["delivered"][number][] = [];
  const frames: OutgoingFrame[] = [];
  const logger = makeLogger();
  const state: { config: NotifyConfig; deliver: ChannelsPort["deliver"] } = {
    config: DEFAULT_CONFIG,
    deliver: async (message, targets) => {
      delivered.push({ message, targets });
      return targets.map(() => ({ status: "ok", stage: "delivered" }));
    },
  };
  const deps: PipelineDeps = {
    enabled: true,
    frames: {
      emit: (payload) => {
        frames.push(payload);
      },
    },
    logger,
    config: { readConfig: () => state.config },
    stores: {
      appendHistory: (entry) => {
        history.push(entry);
      },
      recordStatus: (channelId, status, error) => {
        statuses.push({ channelId, status, error });
      },
    },
    channels: { deliver: (message, targets) => state.deliver(message, targets) },
    ...over,
  };
  installPipeline(deps);
  return {
    deps,
    history,
    statuses,
    delivered,
    frames,
    logger,
    useConfig: (patch = {}) => {
      state.config = configAt(patch);
    },
    onDeliver: (deliver) => {
      state.deliver = deliver;
    },
  };
}

afterEach(() => {
  releasePipeline();
  vi.useRealTimers();
});

describe("种类词汇表", () => {
  // 命名空间撞内置名被判成内置，等于绕过用户确认直接放行一条无归属的通知。
  it("isBuiltinKind 只认内置名；内置名一律不含冒号，与 `<命名空间>:<id>` 天然不相交", () => {
    for (const kind of BUILTIN_KINDS) {
      expect(isBuiltinKind(kind), kind).toBe(true);
    }
    // 撞上内置名的外部 kind 会被误判成内置，而误判方向恰好是「绕过用户确认直接放行」。
    for (const kind of ["ask:foo", "done:x", "ASK", "Ask", "ask ", " ask", "", "unknown"]) {
      expect(isBuiltinKind(kind), kind).toBe(false);
    }
    expect(BUILTIN_KINDS.filter((kind) => kind.includes(":"))).toEqual([]);
  });

  // 运行时白名单漏一档，合法强度会被静默判非法并回落缺省。
  it("强度白名单与值表互相覆盖：运行时白名单漏一档，合法强度会被静默判非法并回落缺省", () => {
    expect(NOTIFY_SEVERITIES).toEqual(["info", "success", "warning", "failure"]);
    for (const kind of BUILTIN_KINDS) {
      expect(NOTIFY_SEVERITIES, kind).toContain(KIND_SEVERITY[kind]);
    }
  });

  // 大小写或空白差异被放行，下游出口会拿到一个查不到映射的档位。
  it("isNotifySeverity 边界：大小写与未知档一律判非法（跨边界值不得被放行）", () => {
    for (const severity of NOTIFY_SEVERITIES) {
      expect(isNotifySeverity(severity), severity).toBe(true);
    }
    for (const value of ["", "Info", "INFO", "critical", " urgency", "info "]) {
      expect(isNotifySeverity(value), value).toBe(false);
    }
  });
});

describe("装配面：单例语义", () => {
  // 未装配时抛错会打断宿主事件链上别人的流程——本方法正是挂在事件链上的。
  it("未装配（或已卸载）时 submit 静默丢弃、release 幂等：宿主事件链上抛错会打断别人的流程", () => {
    expect(() => submit(requestOf())).not.toThrow();

    const harness = assemble();
    releasePipeline();
    expect(() => {
      submit(requestOf());
      releasePipeline();
    }).not.toThrow();
    expect(harness.history).toEqual([]);
    expect(harness.delivered).toEqual([]);
  });

  // 重复装配静默换掉能力面，会让同一进程里出现两套裁决配置。
  it("重复装配当场抛错：单例实例上再装一次是编程错误，不该静默换掉能力面", () => {
    assemble();
    expect(() => assemble()).toThrow(/只能装配一次/u);
  });
});

describe("归档：发出与压制只在载荷上分叉", () => {
  // 压制不落史，用户问「为什么没收到」时没有任何可查的证据。
  it("总开关关：记 suppressed=disabled 且零投递（用户看不到通知时，历史里要有理由）", () => {
    const harness = assemble({ enabled: false });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    expect(harness.history).toHaveLength(1);
    expect(harness.history[0]!.suppressed).toBe("disabled");
    expect(harness.history[0]!.channels).toBeUndefined();
  });

  // 频道全关是合法配置，把它记成发送成功会掩盖「一条都没发出去」。
  it("一个目标都没有：记 suppressed=no-target，而不是一条空的成功记录", () => {
    const harness = assemble();
    harness.useConfig({ channels: builtinsOff() });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    expect(harness.history[0]!.suppressed).toBe("no-target");
  });

  // 两处各取一次时刻，就会出现「历史 12:00:00、收到的通知 12:00:01」。
  it("发出归档：投递载荷与历史记录共用同一个 ts，文案逐字一致", async () => {
    const harness = assemble();
    harness.useConfig({ channels: [...builtinsOff(), barkChannel()] });
    const before = Date.now();
    submit(requestOf({ title: "标题", body: "正文" }));
    await settleMicrotasks();
    const after = Date.now();

    const entry = harness.history[0]!;
    const message = harness.delivered[0]!.message;
    // 两处各取一次时刻是真实的回归形态：历史显示 12:00:00，收到的通知却是 12:00:01。
    expect(entry.ts).toBe(message.ts);
    expect(entry.ts).toBeGreaterThanOrEqual(before);
    expect(entry.ts).toBeLessThanOrEqual(after);
    expect(message.title).toBe("标题");
    expect(message.body).toBe("正文");
    expect(entry.title).toBe("标题");
    expect(entry.message).toBe("正文");
    expect(entry.kind).toBe("done");
  });

  // 日志口径与归档口径不同词，排查时「按日志找记录」这一步就对不上。
  it("kindRoutes 指向已删除频道：warn 与归档同一口径（suppressed:no-target），不静默也不自称 skipped", () => {
    const harness = assemble();
    harness.useConfig({ channels: builtinsOff(), kindRoutes: { done: ["bark:gone"] } });
    submit(requestOf());

    expect(harness.delivered).toEqual([]);
    const archived = harness.history[0]!.suppressed;
    expect(archived).toBe("no-target");
    expect(harness.logger.warns).toHaveLength(1);
    expect(harness.logger.warns[0]).toContain("kindRoutes[done]");
    expect(harness.logger.warns[0]).toContain("bark:gone");
    // 日志点名的那条口径就是历史里记下的那条：`SuppressReason` 里没有 skipped 这个词。
    expect(harness.logger.warns[0]).toContain(`suppressed:${archived}`);
    expect(harness.logger.warns[0]).not.toContain("skipped");
  });

  // 有别的目标时通知照常发出，此时谎称「本条按 suppressed 归档」会把排查引向一条不存在的记录。
  it("stale 但仍有其它目标：其余目标照常投递，warn 不谎称本条通知按 suppressed 归档", async () => {
    const harness = assemble();
    harness.useConfig({
      channels: [...builtinsOff(), barkChannel()],
      kindRoutes: { done: ["bark:gone", "bark:a"] },
    });
    submit(requestOf());
    await settleMicrotasks();

    expect(harness.history[0]!.channels).toEqual([{ channelId: "bark:a", status: "ok" }]);
    expect(harness.logger.warns).toHaveLength(1);
    expect(harness.logger.warns[0]).toContain("bark:gone");
    expect(harness.logger.warns[0]).not.toContain("suppressed:");
  });

  // 节奏状态跨装配期存活，会把上一次运行窗口的节流带进新一次装配。
  it("release 清空逐频道节奏状态：卸载再装配后同一频道重新计时，节流不跨装配期存活", async () => {
    const harness = assemble();
    harness.useConfig(systemOnly());
    vi.setSystemTime(new Date(2026, 0, 15, 12, 0, 0));

    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(1);

    // 同一时刻的第二条：落在 system 出口的 1 秒节流窗口里，不产生第二次投递。
    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(1);
    expect(harness.history).toHaveLength(2);

    releasePipeline();
    installPipeline(harness.deps);
    submit(requestOf());
    await settleMicrotasks();
    expect(harness.delivered).toHaveLength(2);
  });

  // 归档面违约发生在投递之后：不在这里收口，「通知发出去了但历史里没有」就只剩一个未捕获拒绝，
  // 而它挂在宿主事件链上，抛出去会打断别人的流程。
  it("归档面违约经「投递失败」告警收口：既不抛穿，也不静默（这是这条通知唯一的痕迹）", async () => {
    const logger = makeLogger();
    assemble({
      logger,
      stores: {
        appendHistory: () => {
          throw new Error("历史文件不可写");
        },
        recordStatus: () => {},
      },
    });

    submit(requestOf());
    await pollUntil(() => logger.warns.length === 1, "归档违约经日志收口");
    expect(logger.warns[0]).toContain("投递失败");
    expect(logger.warns[0]).toContain("历史文件不可写");
  });
});

