/**
 * dsh-notifier api 域 settings 块 —— GET /config 与 PUT /config。
 *
 * 判据面：写面把请求**形状**（`patch` 是不是非空对象、`expectedRevision` 是不是非负整数）与设置
 * **内容**分开把关，本块只管前者；后者由 config 域写面回答，本块只把它的四态结果映射成四个状态码。
 * 四态不能压扁——压扁之后用户看到的就只剩「保存失败」，而「字段非法」「版本过期」「服务不可用」
 * 要做的事完全不同。故这里逐态断言状态码与机器可判的 `code`，而不是只断言「不是 200」。
 */
import type { IncomingMessage } from "node:http";
import { describe, expect, it } from "vitest";

import type { ConfigPort } from "../../../src/server/api/deps.ts";
import { SettingsEndpoints } from "../../../src/server/api/impl/settings/index.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import { jsonReq, makeRes } from "../../helpers.ts";

/** 视图与写面结果经能力面的签名可达，不请 config 域再多导出一个名字。 */
type SettingsView = ReturnType<ConfigPort["readSettingsView"]>;
type WriteResult = Awaited<ReturnType<ConfigPort["writeConfig"]>>;

const VIEW: SettingsView = {
  user: { notifyAsk: false },
  revision: 7,
  writable: true,
  effective: { notifyAsk: false, notifyTaskDone: true },
};

/** 假请求：body 由 async 迭代器吐出（`readJsonBody` 走的就是这条路）。 */
function makeReq(options: { body?: unknown; rawBody?: string } = {}): IncomingMessage {
  return jsonReq({ method: "PUT", url: "/api/dsh-notifier/config", ...options });
}

/** 假 config 端口：读面给固定视图，写面记账并按用例指定的结果作答。 */
function fakeConfig(result?: WriteResult) {
  const writes: Array<{ patch: unknown; revision?: number }> = [];
  const port: ConfigPort = {
    readConfig: () => ({ ...DEFAULT_CONFIG }),
    readSettingsView: () => VIEW,
    writeConfig: async (patch, revision) => {
      writes.push({ patch, revision });
      return result ?? { ok: true, view: VIEW };
    },
  };
  return { port, writes };
}

/** GET 一次设置视图。 */
function get(result?: WriteResult) {
  const config = fakeConfig(result);
  const { res, rec, json } = makeRes();
  new SettingsEndpoints(config.port).read(makeReq(), res);
  return { rec, json, config };
}

/** PUT 一次设置。 */
async function put(request: { body?: unknown; rawBody?: string }, result?: WriteResult) {
  const config = fakeConfig(result);
  const { res, rec, json } = makeRes();
  await new SettingsEndpoints(config.port).write(makeReq(request), res);
  return { rec, json, config };
}

describe("GET /config：视图的四个事实一次取齐", () => {
  it("回 user / revision / writable / effective 四件事实（分开取会让界面拿旧修订号提交，凭空造出冲突）", () => {
    const { rec, json } = get();
    expect(rec.status).toBe(200);
    const body = json();
    expect(body.ok).toBe(true);
    expect(body.user).toEqual(VIEW.user);
    expect(body.revision).toBe(7);
    expect(body.writable).toBe(true);
    expect(body.effective).toEqual(VIEW.effective);
  });
});

describe("PUT /config：形状把关", () => {
  it("省略 expectedRevision 时不做版本校验，写面只收到 patch", async () => {
    const { rec, json, config } = await put({ body: { patch: { notifyAsk: true } } });
    expect(rec.status).toBe(200);
    expect(config.writes).toHaveLength(1);
    expect(config.writes[0]!.patch).toEqual({ notifyAsk: true });
    expect(config.writes[0]!.revision).toBeUndefined();
    expect(json().ok).toBe(true);
  });

  it("带 expectedRevision 时把修订号原样交给写面（乐观并发是客户端唯一的防覆盖手段）", async () => {
    const { config } = await put({ body: { patch: { notifyAsk: true }, expectedRevision: 3 } });
    expect(config.writes[0]!.revision).toBe(3);
  });

  // 0 是合法的修订号（冷启动后的第一份设置就是 0）。把「显式传 0」当成「省略」，写面就不再比对
  // 版本——用户拿着旧界面提交会静默覆盖别人的改动，而这条路径上没有任何错误可看。
  it("expectedRevision 显式传 0 不等于省略：写面收到的 revision 必须是 0", async () => {
    const { rec, config } = await put({
      body: { patch: { notifyAsk: true }, expectedRevision: 0 },
    });
    expect(rec.status).toBe(200);
    expect(config.writes).toEqual([{ patch: { notifyAsk: true }, revision: 0 }]);
  });

  it("成功体只回 user 与 revision（多回一份 effective 就多一个可能与本地草稿不一致的服务端版本）", async () => {
    const { json } = await put({ body: { patch: { notifyAsk: true } } });
    const body = json();
    expect(body.user).toEqual(VIEW.user);
    expect(body.revision).toBe(7);
    expect("effective" in body).toBe(false);
    expect("writable" in body).toBe(false);
  });

  it.each<[string, unknown]>([
    ["patch 是字符串", { patch: "abc" }],
    ["patch 是空对象", { patch: {} }],
    ["patch 是数组", { patch: [] }],
    ["patch 是 null", { patch: null }],
    ["patch 缺席", {}],
  ])("patch 非法（%s）→ 400 且根本不进写面", async (_label, body) => {
    const { rec, json, config } = await put({ body });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { error: "配置校验失败: patch", hint: "需至少包含一个配置键（patch 不能为空）" },
    });
    expect(config.writes).toEqual([]);
  });

  it.each<[string, unknown]>([
    ["负数", -1],
    ["小数", 1.5],
    ["字符串", "3"],
    ["null", null],
  ])("expectedRevision 非法（%s）→ 400 而不是当成「省略」", async (_label, revision) => {
    const { rec, json, config } = await put({
      body: { patch: { notifyAsk: true }, expectedRevision: revision },
    });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: {
        error: "配置校验失败: expectedRevision",
        hint: "expectedRevision 必须为非负整数或省略",
      },
    });
    expect(config.writes).toEqual([]);
  });

  it("请求体不是合法 JSON 对象 → 400 invalid-json（否则会按「没有 patch」的理由误导排查）", async () => {
    const { rec, json, config } = await put({ rawBody: "{ 这不是 JSON" });
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: {
        code: "invalid-json",
        details: "请求体不是合法 JSON 对象（或超出大小上限）",
      },
    });
    expect(config.writes).toEqual([]);
  });
});

describe("PUT /config：写面四态 → 四个状态码", () => {
  // 第四态（写入异常 → 500 + 固定文案、底层原因只进日志）由**路由层**的异常收口承担
  // （`api/route.test.ts` 的两条 500 用例）。端点这一半的契约是「不吞异常」——吞成 503 会让用户
  // 看到「设置服务不可用」而真正的原因进不了日志（实测：给端点加 `.catch(() => ({ok:false,
  // reason:"unavailable"}))` 之后，原先没有任何用例会红）。
  it("写面抛错 → 端点不吞，异常交给路由层收口成 500", async () => {
    const port: ConfigPort = {
      readConfig: () => ({ ...DEFAULT_CONFIG }),
      readSettingsView: () => VIEW,
      writeConfig: async () => {
        throw new Error("写盘炸了");
      },
    };
    const { res } = makeRes();
    await expect(
      new SettingsEndpoints(port).write(makeReq({ body: { patch: { notifyAsk: true } } }), res),
    ).rejects.toThrow("写盘炸了");
  });

  it("invalid → 400，并把出错的键与提示带回界面（界面要能定位到那一行）", async () => {
    const { rec, json } = await put(
      { body: { patch: { quietHours: "x" } } },
      { ok: false, reason: "invalid", error: { key: "quietHours.start", hint: "格式为 HH:MM" } },
    );
    expect(rec.status).toBe(400);
    expect(json()).toEqual({
      ok: false,
      error: { error: "配置校验失败: quietHours.start", hint: "格式为 HH:MM" },
    });
  });

  it("conflict → 409 且带 SETTINGS_CONFLICT（客户端按 code 分流，不按会翻译的中文文案）", async () => {
    const { rec, json } = await put(
      { body: { patch: { notifyAsk: true }, expectedRevision: 3 } },
      { ok: false, reason: "conflict" },
    );
    expect(rec.status).toBe(409);
    expect(json()).toEqual({
      ok: false,
      error: { error: "版本冲突", code: "SETTINGS_CONFLICT" },
    });
  });

  it("unavailable → 503（界面据此把表单整体置灰，而不是提示用户重试一次没用的保存）", async () => {
    const { rec, json } = await put(
      { body: { patch: { notifyAsk: true } } },
      { ok: false, reason: "unavailable" },
    );
    expect(rec.status).toBe(503);
    expect(json()).toEqual({
      ok: false,
      error: { error: "设置服务不可用", code: "settings-unavailable" },
    });
  });
});

packages/dsh-notifier/test/unit/pipeline.source:
/**
 * dsh-notifier pipeline 域 judge 块 —— 唯一裁决点的判据顺序与边界。
 *
 * 时间纪律：免打扰判定读 `new Date()`，故用 `vi.setSystemTime` 钉住「现在」。三点理由写在这里，
 * 因为这个文件是后续所有时间相关用例的样板：
 *  1. **不调 `vi.useFakeTimers`**：`setSystemTime` 单独用只换掉 `globalThis.Date`，不碰事件循环，
 *     因此与真实 IO 无冲突；开了假时钟就要跟着操心定时器推进。
 *  2. **日期一律本地构造** `new Date(y, m, d, h, mi)`：`getHours()/getMinutes()` 读的是本地时区，
 *     两端同源，于是本文件在任意 `TZ`、任意 pool（forks/threads）下结果一致；写成
 *     `new Date("...Z")` 会在非 UTC 时区下随机红。
 *  3. `afterEach` 必须 `useRealTimers()` 还原被替换的 `Date`，否则同文件后续用例看到伪造的「现在」。
 */
import { afterEach, describe, expect, it, vi } from "vitest";

import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { NotifyConfig } from "../../../src/server/config/impl/model/type.ts";
import { judgeRequest } from "../../../src/server/pipeline/impl/judge/index.ts";
import { BUILTIN_KINDS } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { NotifyKind } from "../../../src/server/pipeline/impl/service/kinds.ts";
import type { NotifyRequest } from "../../../src/server/pipeline/impl/service/type.ts";

/** 事件开关在设置里的键名。 */
type KindSwitchKey =
  | "notifyAsk"
  | "notifyQuestion"
  | "notifyTaskDone"
  | "notifySubagentDone"
  | "notifyTaskError"
  | "notifyTurnEnd";

/** 内置事件 → 它的开关。独立写一遍而不是从源码导：漏配或改名的种类会在这里红，抄源码就恒真了。 */
const KIND_SWITCHES: ReadonlyArray<readonly [NotifyKind, KindSwitchKey]> = [
  ["ask", "notifyAsk"],
  ["question", "notifyQuestion"],
  ["done", "notifyTaskDone"],
  ["subagent-done", "notifySubagentDone"],
  ["error", "notifyTaskError"],
  ["turn-end", "notifyTurnEnd"],
];

/** 跨午夜窗口，用于免打扰与短路顺序两组用例。 */
const QUIET_CROSS_MIDNIGHT: NotifyConfig["quietHours"] = {
  enabled: true,
  start: "22:00",
  end: "08:00",
};

/** 2026-01-15 的某个本地时刻。 */
function at(hour: number, minute: number): Date {
  return new Date(2026, 0, 15, hour, minute, 0);
}

/** 把「现在」钉死并产出配置；`over` 只覆盖本次关心的键。 */
function configAt(now: Date, over: Partial<NotifyConfig> = {}): NotifyConfig {
  vi.setSystemTime(now);
  return { ...DEFAULT_CONFIG, ...over };
}

function request(kind: NotifyKind, over: Partial<NotifyRequest> = {}): NotifyRequest {
  return { kind, title: "标题", body: "正文", ...over };
}

afterEach(() => {
  vi.useRealTimers();
});

describe("judgeRequest 判据顺序：总开关 → kind 开关 → 动态 kind 确认 → 免打扰", () => {
  it("总开关关：短路在最前，连免打扰都不看", () => {
    const config = configAt(at(23, 0), { quietHours: QUIET_CROSS_MIDNIGHT });
    expect(judgeRequest(config, request("done"), false)).toEqual({ ok: false, reason: "disabled" });
  });

  it("kind 开关：六个内置事件各由自己的开关决定", () => {
    for (const [kind, key] of KIND_SWITCHES) {
      const off = configAt(at(12, 0));
      off[key] = false;
      expect(judgeRequest(off, request(kind), true), `${key} 关`).toEqual({
        ok: false,
        reason: "kind-off",
      });

      const on = configAt(at(12, 0));
      on[key] = true;
      expect(judgeRequest(on, request(kind), true), `${key} 开`).toEqual({ ok: true });
    }
  });

  it("内置种类开关覆盖完整：全部置关后除 test 外无一放行（漏配开关键的 kind 会在这里露出来）", () => {
    const allOff = configAt(at(12, 0));
    for (const [, key] of KIND_SWITCHES) allOff[key] = false;
    for (const kind of BUILTIN_KINDS) {
      if (kind === "test") continue;
      expect(judgeRequest(allOff, request(kind), true), kind).toEqual({
        ok: false,
        reason: "kind-off",
      });
    }
  });

  it("test 没有开关也没有免打扰：用户主动按下它，被静音吃掉等于测试按钮失效", () => {
    const config = configAt(at(23, 0), {
      notifyTaskDone: false,
      quietHours: { ...QUIET_CROSS_MIDNIGHT, allowKinds: [] },
    });
    expect(judgeRequest(config, request("test"), true)).toEqual({ ok: true });
  });

  it("kind 开关先于免打扰：开关关时给 kind-off 而不是 quiet", () => {
    const config = configAt(at(23, 0), { notifyTaskDone: false, quietHours: QUIET_CROSS_MIDNIGHT });
    expect(judgeRequest(config, request("done"), true)).toEqual({ ok: false, reason: "kind-off" });
  });

  it("severity 不参与裁决（只影响出站呈现）", () => {
    const config = configAt(at(12, 0));
    expect(judgeRequest(config, request("done", { severity: "failure" }), true)).toEqual({
      ok: true,
    });
  });
});

describe("judgeRequest 动态 kind：确认名单是唯一凭据", () => {
  it("未确认 → unlisted；确认（进 allowKinds）→ 放行", () => {
    expect(judgeRequest(configAt(at(12, 0)), request("demo:report"), true)).toEqual({
      ok: false,
      reason: "unlisted",
    });
    expect(
      judgeRequest(
        configAt(at(12, 0), { allowKinds: ["demo:report"] }),
        request("demo:report"),
        true,
      ),
    ).toEqual({ ok: true });
  });

  it("命名空间撞内置名的 kind 不是内置种类：allowKinds 里写 ask 不会放行 ask:foo", () => {
    // 与 sdk 域 send 守卫同源：`ask:foo` 查不到任何事件开关，放行它等于放行一条无归属的通知。
    const config = configAt(at(12, 0), { allowKinds: ["ask"] });
    expect(judgeRequest(config, request("ask:foo"), true)).toEqual({
      ok: false,
      reason: "unlisted",
    });
  });

  it("动态 kind 也受免打扰约束：确认与免打扰是两道独立的关", () => {
    const config = configAt(at(23, 0), {
      allowKinds: ["demo:report"],
      quietHours: QUIET_CROSS_MIDNIGHT,
    });
    expect(judgeRequest(config, request("demo:report"), true)).toEqual({
      ok: false,
      reason: "quiet",
    });
  });
});

describe("免打扰：窗口两端都是闭开 [start, end)", () => {
  it.each<[number, number, boolean]>([
    [21, 59, true],
    [22, 0, false],
    [23, 59, false],
    [0, 0, false],
    [7, 59, false],
    [8, 0, true],
  ])("跨午夜窗口 22:00–08:00 在 %i:%i 时放行=%s", (hour, minute, allowed) => {
    const config = configAt(at(hour, minute), { quietHours: QUIET_CROSS_MIDNIGHT });
    const verdict = judgeRequest(config, request("done"), true);
    expect(verdict).toEqual(allowed ? { ok: true } : { ok: false, reason: "quiet" });
  });

  it.each<[number, number, boolean]>([
    [12, 59, true],
    [13, 0, false],
    [13, 59, false],
    [14, 0, true],
  ])("同日窗口 13:00–14:00 在 %i:%i 时放行=%s", (hour, minute, allowed) => {
    const config = configAt(at(hour, minute), {
      quietHours: { enabled: true, start: "13:00", end: "14:00" },
    });
    const verdict = judgeRequest(config, request("done"), true);
    expect(verdict).toEqual(allowed ? { ok: true } : { ok: false, reason: "quiet" });
  });

  it("quietHours.enabled=false 时窗口形同不存在", () => {
    const config = configAt(at(23, 0), {
      quietHours: { enabled: false, start: "22:00", end: "08:00" },
    });
    expect(judgeRequest(config, request("done"), true)).toEqual({ ok: true });
  });

  it("时段内仍放行的 kind（quietHours.allowKinds）逐条生效，未列出的照压", () => {
    const config = configAt(at(23, 0), {
      quietHours: { ...QUIET_CROSS_MIDNIGHT, allowKinds: ["error"] },
    });
    expect(judgeRequest(config, request("error"), true)).toEqual({ ok: true });
    expect(judgeRequest(config, request("done"), true)).toEqual({ ok: false, reason: "quiet" });
  });

  it("脏设置不吞通知：时刻解析失败一律算未命中", () => {
    for (const [start, end] of [
      ["25:00", "08:00"],
      ["22:60", "08:00"],
      ["abc", "08:00"],
      ["", "08:00"],
      ["9:30", "08:00"],
      ["22:00", "nope"],
    ]) {
      const config = configAt(at(23, 0), { quietHours: { enabled: true, start, end } });
      expect(judgeRequest(config, request("done"), true), `start=${start} end=${end}`).toEqual({
        ok: true,
      });
    }
  });

  it("零长窗口（start == end）不算命中：它更可能是没填完，而不是「静音一整天」", () => {
    const config = configAt(at(23, 0), {
      quietHours: { enabled: true, start: "22:00", end: "22:00" },
    });
    expect(judgeRequest(config, request("done"), true)).toEqual({ ok: true });
  });
});

