  it("客户端预设表只消费共享面（认证默认值按设计仍留客户端）", () => {
    // 预设表随 webhookCard 搬到 settings/channels/webhook-card.tsx：读取对象改指卡文件，字面量与
    // 判据强度不变。index.tsx 一并扫，防「搬走时顺手复制第二份」。
    const src = read("src/client/settings/channels/webhook-card.tsx");
