/**
 * dsh-notifier channels 域 browser 出口 —— 跨端通知帧的构造。
 *
 * 帧是本域唯一的线协议产物（宿主 → 客户端），判据只有两条：
 *  - 铃声决议：页面在「只响不弹」时没有能发系统提示音的实体，只能自播；决议错了表现为
 *    用户开了声音却一声不响，或不该响的时候响；
 *  - 上限与可选键：正文进帧前必须按页面侧的上限截断，而 `severity` 缺席要**不写键**而不是写
 *    `undefined`——线协议两侧对「这个键在不在」的解释不同。
 * 帧出口用假实现收帧，本块不需要真推送设施。
 */
import { describe, expect, it } from "vitest";

import { sendBrowser } from "../../../src/server/channels/impl/browser/index.ts";
import type { BrowserTarget, NotifyFrame } from "../../../src/server/channels/impl/browser/type.ts";
import type { NotifyMessage } from "../../../src/server/channels/impl/deliver/type.ts";

function messageOf(over: Partial<NotifyMessage> = {}): NotifyMessage {
  return { title: "标题", body: "正文", kind: "done", ts: 1_700_000_000_000, ...over };
}

/** 收帧的假出口：帧是这条出口的唯一产物，收到即投递完成。 */
function collector(): {
  frames: NotifyFrame[];
  targetOf: (over?: Partial<BrowserTarget>) => BrowserTarget;
} {
  const frames: NotifyFrame[] = [];
  return {
    frames,
    targetOf: (over = {}) => ({
      type: "browser",
      popup: true,
      sound: true,
      whenVisible: false,
      emitFrame: (frame) => {
        frames.push(frame);
      },
      ...over,
    }),
  };
}

describe("sendBrowser", () => {
  // 只响不弹时页面里没有能发系统提示音的实体，判错就是「开了声音却一声不响」。
  it("铃声决议：false 静音，跟随系统按弹不弹分叉，显式音色走自播", () => {
    const { frames, targetOf } = collector();
    const first = sendBrowser(targetOf({ sound: false }), messageOf());
    sendBrowser(targetOf({ sound: true, popup: true }), messageOf());
    sendBrowser(targetOf({ sound: true, popup: false }), messageOf());
    sendBrowser(targetOf({ sound: "ding", popup: true }), messageOf());

    expect(frames.map((frame) => frame.sound)).toEqual([
      { mode: "silent" },
      { mode: "system" },
      { mode: "selfplay" },
      { mode: "selfplay", tone: "ding" },
    ]);
    expect(frames.map((frame) => frame.pop)).toEqual([true, true, false, true]);
    // 交给帧出口即完成：页面弹没弹不是宿主能证明的事，证据上限只能是 accepted。
    expect(first).toEqual({ status: "ok", stage: "accepted" });
  });

  // 写成 undefined 的 severity 键会被客户端读成「显式声明了空强度」；正文超限则显示被截断或整条丢弃。
  it("按页面侧上限截断标题与正文，severity 缺席就不写这个键，可见性随帧下发", () => {
    const { frames, targetOf } = collector();
    sendBrowser(targetOf(), messageOf({ title: "题".repeat(100), body: "文".repeat(3000) }));
    sendBrowser(targetOf({ whenVisible: true }), messageOf({ severity: "warning" }));

    expect(Array.from(frames[0]!.title)).toHaveLength(64);
    expect(Array.from(frames[0]!.body)).toHaveLength(2048);
    expect("severity" in frames[0]!).toBe(false);
    expect(frames[1]!.severity).toBe("warning");
    // 可见性只有页面知道，故随帧下发：渲染端回查配置会读到可能已经变过的那一份。
    expect(frames.map((frame) => frame.whenVisible)).toEqual([false, true]);
  });

  // 什么都不发也是一次投递，只是没有动作：发空帧会推进序号、进重放缓冲、并让页面认领主标签租约，
  // 而记成 ok 会让历史里多出一条没发生过的成功。判据必须把「出口自己的回答」钉死在结果上。
  it("弹窗与声音都关：不发帧，收成 skipped 而不是伪造一次投递成功", () => {
    const { frames, targetOf } = collector();
    const result = sendBrowser(targetOf({ popup: false, sound: false }), messageOf());

    // 成因经 code 带出去（与 system 出口同一个 code）：两个出口的「用户都关了」是同一件事
    expect(result).toEqual({
      status: "skipped",
      reason: { code: "reasonSkipConfig" },
    });
    expect(frames).toEqual([]);
  });
});

packages/dsh-notifier/test/unit/shared/r.source:
/**
 * dsh-notifier src/shared —— 理由 code 闭集的直连判据。
 *
 * 这次收口的起因：客户端有一份 `const LEGACY_CODE = "reasonLegacy"`，注释自述「与服务端
 * REASON_LEGACY 同值」，而没有任何断言锁住两者相等——改一边就是一个读不出来的历史行。
 * 收口后两端消费同一个绑定，「同值」由构造保证；本文件再把值、成员与「客户端不再有第二份
 * 字面量」钉成可判红的判据。
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import { REASON_CODES, REASON_LEGACY } from "../../../src/shared/interface.ts";

const pkgDir = fileURLToPath(new URL("../../../", import.meta.url));

describe("REASON_LEGACY", () => {
  it("字面量与表内位置都钉住（旧散文的收编 code 只有一个）", () => {
    expect(REASON_LEGACY).toBe("reasonLegacy");
    expect(REASON_CODES[0]).toBe(REASON_LEGACY);
    expect(REASON_CODES).toContain(REASON_LEGACY);
  });
});

describe("REASON_CODES", () => {
  it("成员与顺序逐项钉住（新增 code 必须显式落在这张表上）", () => {
    expect([...REASON_CODES]).toEqual([
      "reasonLegacy",
      "reasonSkipConfig",
      "reasonSkipEnvironment",
      "reasonSystemPopupFailed",
      "reasonSystemSoundFailed",
      "reasonSystemToastScriptMissing",
      "reasonSystemToneUnwritable",
      "reasonBarkRequestFailed",
      "reasonBarkHttp",
      "reasonBarkRejected",
      "reasonBarkBodyUnreadable",
      "reasonWebhookTemplateInvalid",
      "reasonWebhookRequestFailed",
      "reasonWebhookHttp",
      "reasonUnknownTarget",
      "reasonChannelThrew",
      "reasonThrottled",
    ]);
  });

  // 重复项不改变联合类型，却会让客户端的穷尽表看起来更全：漏一条文案仍能编译过。
  it("无重复项", () => {
    expect(new Set(REASON_CODES).size).toBe(REASON_CODES.length);
  });
});

describe("单点化：客户端不再抄一份同值字面量", () => {
  const clientSrc = () => readFileSync(join(pkgDir, "src/client/reason-text.ts"), "utf8");

  // 这一段只留「有没有 / 多没多」的最小结构锚，**不留计数**。为什么：本文件从 import.meta.url
  // 推导包目录去读盘，变异沙箱内读到的是被变异体包装过的同一份文件，于是「出现几次」这类断言
  // 锁的是环境而不是行为——CI 上它曾以 expected 5 to be 3 直接把该变异段的 dry run 判死。
  // 「客户端不再有第二份字面量」这件事无法用行为表达（两份字面量同值时行为完全一致），故只能
  // 靠结构锚；而 reasonLegacy 的行为判据在 test/client-unit/reason-text.test.ts 里（喂带 detail
  // 与不带 detail 两种输入，断主文案与 detail 去重），不在这里重复一遍。
  it("客户端引用共享绑定，LEGACY_CODE 已不存在", () => {
    const src = clientSrc();
    expect(src).not.toMatch(/LEGACY_CODE/u);
    expect(src).toContain("REASON_LEGACY");
    expect(src).toContain('from "../shared/interface.ts"');
  });

  it("客户端引用的是共享面而不是宿主实现（类型面同理）", () => {
    const src = clientSrc();
    expect(src).not.toContain("../server/");
    // 类型面必须仍是 import type：值引会把宿主实现拖进浏览器产物
    expect(src).toMatch(/import type \{[^}]*ReasonCode[^}]*\} from "\.\.\/shared\/interface\.ts"/u);
  });
});

describe("宿主实现侧：code 闭集是转出而不是第二份声明", () => {
  it("src/server/shared/reason.ts 只保留值函数与转出", () => {
    const src = readFileSync(join(pkgDir, "src/server/shared/reason.ts"), "utf8");
    expect(src).not.toMatch(/export const REASON_LEGACY/u);
    expect(src).not.toMatch(/export const REASON_CODES/u);
    expect(src).toMatch(/export \{ REASON_CODES, REASON_LEGACY \};/u);
    // 值函数仍在（它们依赖 ./text.ts，进不了零 import 的共享面）
    for (const fn of [
      "export function reason(",
      "export function reasonFromCause(",
      "export function normalizeReason(",
      "export function sameReasonShape(",
      "export function clampReasonDetail<",
    ]) {
      expect(src, fn).toContain(fn);
    }
  });
});

packages/dsh-notifier/test/unit/config/m.source:
/**
 * dsh-notifier config 域 model 块 —— 默认形态与布尔键清单。
 *
 * 为什么默认值要在这里用手写字面量再写一遍：本域其余用例的期望值都取自 `DEFAULT_CONFIG[key]`
 * 本身，而实现的回落源就是同一个对象——两侧同源同变，把 `notifyAsk: true` 改成 `false` 之后
 * 全套测试照样绿。而默认值同时是设置页的初始形态与跨端契约（客户端按同一份形状渲染），
 * 不能是「实现说什么就是什么」：它必须有一份独立于实现的书面形态。
 *
 * `BOOLEAN_KEYS` 同理——它是校验闸门的分支依据，漏登记一个键就等于该键的布尔闸门静默消失
 * （陌生键落到校验的兜底出口即放行），故清单也在测试里手写一份，两边逐字对齐。
 *
 * 本块是 L1 纯函数块，直引 `impl/model/index.ts` 与 `impl/input/index.ts`。
 */
import { describe, expect, it } from "vitest";

import {
  BOOLEAN_KEYS,
  normalizeConfig,
  validateSettings,
} from "../../../src/server/config/impl/input/index.ts";
import { DEFAULT_CONFIG } from "../../../src/server/config/impl/model/index.ts";
import type { RawSettingValue } from "../../../src/server/config/impl/model/type.ts";

/** 手写默认形态：与实现零共享（不 import 它的任何取值），改动默认值必须在这里也显式改一次。 */
const EXPECTED_DEFAULTS = {
  notifyAsk: true,
  notifyQuestion: true,
  notifyTaskDone: true,
  notifySubagentDone: false,
  notifyTaskError: true,
  notifyTurnEnd: false,

  quietHours: { enabled: false, start: "22:00", end: "08:00" },
  // 两条内置频道是默认形态的一部分：读面靠它们才谈得上「与默认表逐字一致」，权威形态也住在它们身上。
  channels: [
    { type: "browser", id: "browser", enabled: true, popup: true, sound: true, whenVisible: false },
    { type: "system", id: "system", enabled: true, popup: true, sound: true },
  ],
  kindRoutes: {},
  allowKinds: [],

  historyMaxAgeDays: 0,
} as const;

/** 受布尔闸门管的键：手写清单，与实现的 `BOOLEAN_KEYS` 是两份独立文本。 */
const BOOLEAN_SETTING_KEYS: readonly string[] = [
  "notifyAsk",
  "notifyQuestion",
  "notifyTaskDone",
  "notifySubagentDone",
  "notifyTaskError",
  "notifyTurnEnd",
];

describe("DEFAULT_CONFIG：默认形态以手写字面量为准，不由实现自述", () => {
  it("整份默认设置等于手写形态：布尔偏置、两条内置条目与计数/列表类默认值逐个锚住（改坏一行不该悄无声息）", () => {
    expect(DEFAULT_CONFIG).toEqual(EXPECTED_DEFAULTS);
  });

  it("空输入归一化后与默认表逐字相等：默认表同时是读面的物化基准（两侧不等就说明物化补了默认表没有的东西）", () => {
    expect(normalizeConfig({})).toEqual(DEFAULT_CONFIG);
  });

  it("quietHours 只有 enabled / start / end：allowKinds 缺省表示「时段内不额外放行谁」（整体相等看不出多出来的键值是 undefined）", () => {
    expect(Object.keys(DEFAULT_CONFIG.quietHours)).toEqual(["enabled", "start", "end"]);
    expect("allowKinds" in DEFAULT_CONFIG.quietHours).toBe(false);
  });
});

describe("BOOLEAN_KEYS：布尔闸门的清单必须覆盖每个布尔键", () => {
  it("清单逐字一致，且清单里每个键的非布尔值都被拦下并指向它自己（漏登记一个键 = 该键的闸门静默消失）", () => {
    expect([...BOOLEAN_KEYS].sort()).toEqual([...BOOLEAN_SETTING_KEYS].sort());

    for (const key of BOOLEAN_SETTING_KEYS) {
      const patch: Record<string, RawSettingValue> = { [key]: 1 };
      const verdict = validateSettings(patch);
      if (verdict.ok) throw new Error(`${key} 的非布尔值被判放行`);
      expect(verdict.error.key, key).toBe(key);
      expect(verdict.error.hint, key).toContain("true 或 false");
    }
  });
});

packages/dsh-notifier/test/client-unit/m.source:
/**
 * dsh-notifier — 凭据掩码编辑语义的判据（#769 阶段 0）。
 *
 * 要锁的不是「函数返回值对不对」，而是**掩码永远不会作为可编辑字面量进入输入框**：旧实现把
 * 服务端掩码直接渲染成 value，用户在圆点后追加一个字符就得到「掩码+新字符」，提交时不再等于
 * 掩码，服务端把它当新凭据落盘（redact 的还原判据是严格相等）。
 */
import { describe, expect, it } from "vitest";

import {
  CREDENTIAL_MASK_PLACEHOLDER,
  credentialFieldKey,
  credentialFieldView,
  isCredentialConfigured,
  maskedFieldValue,
} from "../../src/client/settings/mask.ts";

const MASK_FROM_SERVER = "********";

describe("凭据字段：已配置判定", () => {
  it("服务端掩码与非空新值都算已配置", () => {
    expect(isCredentialConfigured(MASK_FROM_SERVER)).toBe(true);
    expect(isCredentialConfigured("device-key-abc")).toBe(true);
  });

  it("缺失与空串都算未配置（读面把空串剥成缺键）", () => {
    expect(isCredentialConfigured(undefined)).toBe(false);
    expect(isCredentialConfigured(null)).toBe(false);
    expect(isCredentialConfigured("")).toBe(false);
    expect(isCredentialConfigured(42)).toBe(false);
  });
});

describe("凭据字段：渲染值", () => {
  it("未编辑时渲染空值——掩码不得成为可编辑字面量", () => {
    expect(maskedFieldValue(MASK_FROM_SERVER, false)).toBe("");
    expect(maskedFieldValue("device-key-abc", false)).toBe("");
  });

  it("编辑后渲染草稿值（含用户清空的情形）", () => {
    expect(maskedFieldValue("new-key", true)).toBe("new-key");
    expect(maskedFieldValue("", true)).toBe("");
  });

  it("已配置且未编辑时：值空、占位为掩码提示（用户不会打在掩码上）", () => {
    const view = credentialFieldView(MASK_FROM_SERVER, false, "访问令牌");
    expect(view).toEqual({
      value: "",
      placeholder: CREDENTIAL_MASK_PLACEHOLDER,
      configured: true,
    });
  });

  it("未配置时：值空、占位回落到字段自己的说明", () => {
    expect(credentialFieldView(undefined, false, "访问令牌")).toEqual({
      value: "",
      placeholder: "访问令牌",
      configured: false,
    });
  });

  it("编辑后：值取草稿、占位仍按已配置与否决定", () => {
    expect(credentialFieldView(MASK_FROM_SERVER, true, "访问令牌")).toEqual({
      value: MASK_FROM_SERVER,
      placeholder: CREDENTIAL_MASK_PLACEHOLDER,
      configured: true,
    });
    expect(credentialFieldView("", true, "访问令牌").value).toBe("");
  });

  it("瞬态键按频道与字段区分：同名字段在不同实例上互不串味", () => {
    expect(credentialFieldKey("bark-1", "deviceKey")).toBe("bark-1:deviceKey");
    expect(credentialFieldKey("bark-1", "deviceKey")).not.toBe(
      credentialFieldKey("bark-2", "deviceKey"),
    );
    expect(credentialFieldKey("wh-1", "token")).not.toBe(credentialFieldKey("wh-1", "password"));
  });

  it("占位提示不承载真实凭据值，也不等于服务端掩码字面量", () => {
    expect(CREDENTIAL_MASK_PLACEHOLDER).not.toBe(MASK_FROM_SERVER);
    // 精确值锚：空串能通过上面的 not.toBe（它不等于任何非空掩码），却让「已配置」的提示整体
    // 消失，用户看不出这一格已经有值。占位形态要改就在这条判据里显式改。
    expect(CREDENTIAL_MASK_PLACEHOLDER).toBe("••••••••");
  });
});

packages/dsh-notifier/test/client-unit/n.source:
/**
 * dsh-notifier — 标题闪烁的判据（#769 阶段 3）。
 *
 * 「隐藏时收到通知 → 标题变 🔔 → 卸载」是本包唯一会让标题永久卡死的路径（恢复只发生在回前台
 * 与卸载两处）。这里用假 document 把恢复语义钉住：只记第一次的原始标题、restore 幂等，以及
 * 归属判定——热更时旧实例的 disposer 不许摘掉新实例点亮的闪烁（那是通知被静音/无权限时唯一
 * 的可见提醒）。
 */
import { describe, expect, it } from "vitest";

import { createTitleFlasher } from "../../src/client/notify/title.ts";

function harness(initial = "DSH") {
  const doc = { title: initial };
  const flasher = createTitleFlasher({
    get: () => doc.title,
    set: (value: string) => {
      doc.title = value;
    },
  });
  // 归属令牌：一枚令牌 = 一次 apply 建立的实例；跨实例场景由用例另取
  const owner: object = {};
  return { doc, flasher, owner };
}

describe("标题闪烁", () => {
  it("闪烁时把标题换成带铃铛的短标题", () => {
    const h = harness();
    h.flasher.flash("任务完成", h.owner);
    expect(h.doc.title).toBe("🔔 任务完成");
  });

  it("连续闪烁只记第一次的原始标题（否则恢复出来的是上一个 🔔 标题）", () => {
    const h = harness("原名");
    h.flasher.flash("第一条", h.owner);
    h.flasher.flash("第二条", h.owner);
    expect(h.doc.title).toBe("🔔 第二条");
    h.flasher.restore(h.owner);
    expect(h.doc.title).toBe("原名");
  });

  it("超长标题截到 40 字符（标题栏放不下，也不该被长文本挤爆）", () => {
    const h = harness();
    h.flasher.flash("x".repeat(100), h.owner);
    expect(h.doc.title).toBe("🔔 " + "x".repeat(40));
  });

  it("restore 幂等：没闪过或闪完再调都不改变标题", () => {
    const h = harness("原名");
    h.flasher.restore(h.owner);
    expect(h.doc.title).toBe("原名");
    h.flasher.flash("一次", h.owner);
    h.flasher.restore(h.owner);
    h.flasher.restore(h.owner);
    expect(h.doc.title).toBe("原名");
  });

  it("恢复后可再次闪烁（卸载后重新挂载的路径）", () => {
    const h = harness("原名");
    h.flasher.flash("第一次", h.owner);
    h.flasher.restore(h.owner);
    h.flasher.flash("第二次", h.owner);
    expect(h.doc.title).toBe("🔔 第二次");
    h.flasher.restore(h.owner);
    expect(h.doc.title).toBe("原名");
  });

  it("旧实例的 restore 摘不掉新实例的闪烁（归属判定）", () => {
    const h = harness("原名");
    const first: object = {};
    const second: object = {};
    h.flasher.flash("甲通知", first);
    h.flasher.flash("乙通知", second);
    expect(h.doc.title).toBe("🔔 乙通知");

    // 热更时旧实例的 disposer 仍会执行：它一 restore，用户就看不到隐藏页收到的通知了
    h.flasher.restore(first);
    expect(h.doc.title).toBe("🔔 乙通知");

    h.flasher.restore(second);
    expect(h.doc.title).toBe("原名");
  });

  it("归属者自己恢复之后，旧实例再 restore 仍是 no-op", () => {
    const h = harness("原名");
    const first: object = {};
    const second: object = {};
    h.flasher.flash("甲通知", first);
    h.flasher.flash("乙通知", second);
    h.flasher.restore(second);
    expect(h.doc.title).toBe("原名");
    h.flasher.restore(first);
    expect(h.doc.title).toBe("原名");
  });
});

